CREATE TABLE "Aluno" ("id" UUID PRIMARY KEY, "nome" TEXT NOT NULL, "telefone" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "dataNascimento" VARCHAR(10) NOT NULL, "faixa" TEXT NOT NULL, "dataMatricula" VARCHAR(10) NOT NULL, "situacao" TEXT NOT NULL DEFAULT 'ativo', "criadoEm" TEXT NOT NULL);
CREATE TABLE "Mensalidade" ("id" UUID PRIMARY KEY, "alunoId" UUID NOT NULL REFERENCES "Aluno"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "competencia" VARCHAR(7) NOT NULL, "valorCentavos" INTEGER NOT NULL CHECK ("valorCentavos" > 0), "dataVencimento" VARCHAR(10) NOT NULL, "dataPagamento" VARCHAR(10), "criadoEm" TEXT NOT NULL, CONSTRAINT "Mensalidade_alunoId_competencia_key" UNIQUE ("alunoId", "competencia"));
CREATE INDEX "Mensalidade_dataVencimento_idx" ON "Mensalidade"("dataVencimento");
CREATE TABLE "Presenca" ("id" UUID PRIMARY KEY, "alunoId" UUID NOT NULL REFERENCES "Aluno"("id") ON DELETE CASCADE ON UPDATE CASCADE, "dataTreino" VARCHAR(10) NOT NULL, "tipoTreino" TEXT NOT NULL, "presente" BOOLEAN NOT NULL, CONSTRAINT "Presenca_alunoId_dataTreino_tipoTreino_key" UNIQUE ("alunoId", "dataTreino", "tipoTreino"));
CREATE TABLE "Analise" ("id" UUID PRIMARY KEY, "pergunta" TEXT NOT NULL, "resposta" TEXT NOT NULL, "modelo" TEXT NOT NULL, "usuario" TEXT NOT NULL, "metricas" TEXT NOT NULL, "criadoEm" TEXT NOT NULL);
